// Debug - show what data we have
const item = $input.first().json;

console.log('=== DEBUG: URL Data ===');
console.log('Raw item:', JSON.stringify(item, null, 2));

// Prepare the data more safely
const urlData = {
  url_id: parseInt(item.id),
  url: String(item.url || ''),
  name: String(item.name || ''),
  expected_response: item.expected_response || null,
  timeout: (parseInt(item.timeout_seconds) || 30) * 1000,
  failure_threshold: parseInt(item.failure_threshold) || 5,
  current_failures: parseInt(item.current_failure_count) || 0,
  priority: String(item.priority || 'normal'),
  expected_chars: parseInt(item.expected_response_chars) || 200,
  http_method: String(item.http_method || 'GET'),
  check_start_time: Date.now()
};

console.log('=== DEBUG: Prepared Data ===');
console.log('Prepared urlData:', JSON.stringify(urlData, null, 2));

return {
  json: urlData
};

// Debug response processing with better HTTP handling
const inputItem = $input.first();
const urlData = $('Debug Prepare Data').first().json;

console.log('=== DEBUG: HTTP Response ===');
console.log('HTTP inputItem keys:', Object.keys(inputItem.json || {}));
console.log('HTTP inputItem.json.data length:', (inputItem.json?.data || '').length);
console.log('HTTP inputItem error:', inputItem.error);

let status = 'error';
let errorMessage = null;
let responseTime = Date.now() - urlData.check_start_time;
let httpStatusCode = null;
let responsePreview = null;

try {
  if (inputItem.json && !inputItem.error) {
    const response = inputItem.json;

    // Check for different possible status code fields
    httpStatusCode = response.statusCode || response.status || response.code;

    // If we have response data and no explicit error, assume success
    if (response.data && response.data.length > 0) {
      status = 'up';
      httpStatusCode = 200;  // Force 200 if we got data
      const responseBody = String(response.data || '');
      responsePreview = responseBody.substring(0, urlData.expected_chars);
      console.log('Got response data, assuming status 200');
    } else if (httpStatusCode && httpStatusCode >= 200 && httpStatusCode < 300) {
      status = 'up';
      const responseBody = String(response.body || response.data || '');
      responsePreview = responseBody.substring(0, urlData.expected_chars);
    } else {
      status = 'down';
      errorMessage = `HTTP ${httpStatusCode || 'unknown'}`;
    }
  } else {
    status = 'error';
    errorMessage = String(inputItem.error?.message || 'HTTP request failed');
  }
} catch (error) {
  status = 'error';
  errorMessage = String(error.message || 'Unknown error');
}

const result = {
  url_id: urlData.url_id,
  url: urlData.url,
  name: urlData.name,
  status: status,
  response_time_ms: responseTime,
  http_status_code: httpStatusCode,
  response_body_preview: responsePreview ? String(responsePreview) : null,
  error_message: errorMessage,
  checked_at: new Date().toISOString().slice(0, 19).replace('T', ' ')
};

console.log('=== DEBUG: Final Result ===');
console.log('Final result:', JSON.stringify(result, null, 2));

return {
  json: result
};

// Get data from the previous node more explicitly
const saveReportResult = $input.first().json;

// Try to get the original data from the Debug Process Response node
const processResponseData = $('Debug Process Response').first().json;

console.log('=== DEBUG: Before UPDATE Query ===');
console.log('Data from Save Report node:', JSON.stringify(saveReportResult, null, 2));
console.log('Data from Process Response node:', JSON.stringify(processResponseData, null, 2));

// Use the process response data since it has all the fields
const result = processResponseData;

console.log('Using data:');
console.log('- url_id:', result.url_id, '(type:', typeof result.url_id, ')');
console.log('- status:', result.status, '(type:', typeof result.status, ')');

// Validate data before building SQL
if (!result.url_id || !result.status) {
  console.error('ERROR: Missing required data!');
  console.error('url_id:', result.url_id);
  console.error('status:', result.status);
  throw new Error('Missing url_id or status data');
}

// Build the SQL query manually
const sqlQuery = `UPDATE monitored_urls SET last_checked_at = NOW(), last_status = '${result.status}' WHERE id = ${result.url_id};`;
console.log('- SQL Query:', sqlQuery);

return {
  json: {
    url_id: result.url_id,
    status: result.status,
    sql_query: sqlQuery
  }
};

const result = $input.first().json;

console.log('=== DEBUG: UPDATE SUCCESS ===');
console.log('UPDATE query executed successfully!');
console.log('URL ID updated:', result.url_id);
console.log('New status:', result.status);

return {
  json: {
    success: true,
    url_id: result.url_id,
    status: result.status,
    message: 'Health check completed and database updated successfully'
  }
};
